node --input-type=module <<'NODE'
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {performance} from 'node:perf_hooks';import {taskRead} from '/opt/homebrew/lib/node_modules/@vxu-labs/dip/src/core.js';import {readingCommand} from '/opt/homebrew/lib/node_modules/@vxu-labs/dip/src/workflow.js';
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'dip-history-plan-'));try{
 const repo={root:tmp,dir:path.join(tmp,'.dip'),branch:'main',config:{}};
 for(const n of [10,100,500,1000]){const id='task_'+n;const dir=path.join(repo.dir,'events',id);fs.mkdirSync(dir,{recursive:true});
 for(let i=0;i<n;i++)fs.writeFileSync(path.join(dir,`${i}.json`),JSON.stringify({schemaVersion:1,eventId:'e'+i,taskId:id,type:i?'task.checkpoint':'task.create',actor:'fixture',createdAt:'2026-10-28T00:00:00Z',parents:i?['e'+(i-1)]:[],payload:i?{summary:'Synthetic checkpoint'}:{title:'Synthetic task',status:'backlog'}}));
 const times=[];for(let i=0;i<4;i++){const t=performance.now();taskRead(repo,id);times.push(Number((performance.now()-t).toFixed(2)));}console.log(JSON.stringify({eventsPerTask:n,readMs:times}));}
 console.log(JSON.stringify({readClassification:Object.fromEntries(['cat README.md','rg -n TODO src','git status --short','cat README.md; cat package.json','rg --files | head -20'].map(cmd=>[cmd,readingCommand({cmd})]))}));
}finally{fs.rmSync(tmp,{recursive:true,force:true});}
